use moloch_replay::engine::Engine;
use serde_json::{Value,json};
fn policy()->Value{json!({"initialCash":"1000.000000","maximumCommitted":"800.000000","maximumMarketCost":"100.000000","maximumMarkets":3,"quantity":5,"inventoryExitMode":"fixedGain","maximumInventoryAgeMs":60000,"inventoryMinimumGain":"0.005000","inventoryAgeClock":"execution"})}
fn adoption()->Value{json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"tournamentId":"cup","receiptHash":"a".repeat(64),"requestStartedAt":"2026-10-15T00:00:00Z","receivedAt":"2026-10-15T00:00:00.001Z","processedAt":"2026-10-15T00:00:00.002Z","openingCost":"3.450000","effectiveMaximumMarkets":4,"positions":[{"exchangeId":"900","marketId":"211","quantity":-5,"lotPrincipal":"3.450000","reportedCostBasis":"3.450000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"104421690","quantity":5,"side":"NO","entryPrice":"0.690000","openedAt":"2026-10-09T02:23:38.1711908+00:00"}]}]})}
fn book(exchange:&str,market:&str,at:&str)->Value{json!({"type":"book","receivedAt":at,"book":{"tournamentId":"cup","marketId":market,"exchangeId":exchange,"requestStartedAt":at,"receivedAt":at,"sourceAt":at,"sequence":"1","bids":[{"price":"0.200000","quantity":100}],"asks":[{"price":"0.300000","quantity":100}]}})}
fn actual(kind:&str,q:&Value,at:&str)->Value{json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"b".repeat(64),"orderId":q["id"],"actualOrderId":"201","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":at})}
fn adopted()->Engine{let mut engine=Engine::new_live(&policy()).unwrap();engine.advance(&adoption()).unwrap();engine}
#[test]fn opening_basis_moves_attributed_cash_without_importing_fills_or_profit(){let e=adopted();let r=e.report().unwrap();assert_eq!(r["cash"],"996.550000");assert_eq!(r["ownedCost"],"3.450000");assert_eq!(r["realized"],"0.000000");assert_eq!(r["openingInventoryCost"],"3.450000");assert_eq!(r["fills"],0);assert_eq!(r["orders"],0);assert_eq!(e.opening_inventory_cost(),3_450_000);assert_eq!(e.policy()["maximumMarkets"],4);assert!(r["positions"]["900"]["NO"][0].get("executedAt").is_none());assert_eq!(r["inheritedInventory"]["sourcePositions"][0]["lots"][0]["openedAt"],"2026-10-09T02:23:38.1711908+00:00");assert_eq!(r["inheritedInventory"]["officialAccountRealizedPnl"],Value::Null);e.wallet.audit().unwrap();}
#[test]fn ancient_acquisition_does_not_create_an_instant_forced_loss_exit(){let mut e=adopted();e.advance(&book("900","211","2026-10-15T00:00:01Z")).unwrap();let sell=e.order_records().into_iter().find(|q|q["action"]=="sell").unwrap();assert!(sell.get("inventoryExitReason").is_none());assert!(sell.get("executionStyle").is_none());assert_eq!(sell["price"],"0.695000");}
#[test]fn inherited_sale_preserves_constant_opening_basis_and_separates_new_profit(){let mut e=adopted();e.advance(&book("900","211","2026-10-15T00:00:01Z")).unwrap();let q=e.order_records().into_iter().find(|q|q["action"]=="sell").unwrap();e.advance(&actual("actual_order_ack",&q,"2026-10-15T00:00:02Z")).unwrap();let mut f=actual("actual_fill",&q,"2026-10-15T00:00:05Z");f["fillId"]=json!("301");f["quantity"]=json!(2);f["price"]=json!("0.700000");f["fee"]=json!("0.000000");f["executedAt"]=json!("2026-10-15T00:00:04Z");e.advance(&f).unwrap();let r=e.report().unwrap();assert_eq!(r["openingInventoryCost"],"3.450000");assert_eq!(r["ownedCost"],"2.070000");assert_eq!(r["realized"],"0.020000");assert_eq!(r["inheritedRealizedGross"],"0.020000");assert_eq!(r["newTradingRealized"],"0.000000");assert_eq!(r["fills"],1);assert_eq!(e.live_order_bindings().len(),1);e.wallet.audit().unwrap();}
#[test]fn material_reported_basis_difference_is_explicit_and_does_not_block_management(){let mut a=adoption();a["positions"][0]["reportedCostBasis"]=json!("3.000000");a["positions"][0]["reportedMinusLotPrincipal"]=json!("-0.450000");a["positions"][0]["basisClassification"]=json!("reported_discrepancy");let mut e=Engine::new_live(&policy()).unwrap();e.advance(&a).unwrap();let r=e.report().unwrap();assert_eq!(r["ownedCost"],"3.450000");assert_eq!(r["inheritedInventory"]["sourcePositions"][0]["reportedCostBasis"],"3.000000");assert_eq!(r["inheritedInventory"]["sourcePositions"][0]["basisClassification"],"reported_discrepancy");}
#[test]fn duplicate_side_quantity_cost_coverage_and_clock_errors_are_atomic(){for case in ["quantity","side","duplicate","cost","basis_metadata","coverage","authority","clock","market_limit"]{let mut a=adoption();match case{"quantity"=>a["positions"][0]["lots"][0]["quantity"]=json!(6),"side"=>a["positions"][0]["lots"][0]["side"]=json!("YES"),"duplicate"=>{let row=a["positions"][0].clone();a["positions"].as_array_mut().unwrap().push(row);},"cost"=>a["positions"][0]["lotPrincipal"]=json!("3.440000"),"basis_metadata"=>a["positions"][0]["reportedCostBasis"]=json!("3.000000"),"coverage"=>a["complete"]=json!(false),"authority"=>a["authority"]=json!("other_agent"),"clock"=>a["processedAt"]=json!("2026-10-15T00:01:00Z"),_=>a["effectiveMaximumMarkets"]=json!(30)}let mut e=Engine::new_live(&policy()).unwrap();let before=e.report().unwrap();assert!(e.advance(&a).is_err(),"{case}");assert_eq!(e.report().unwrap(),before,"{case}");}let mut e=adopted();let before=e.report().unwrap();assert!(e.advance(&adoption()).is_err());assert_eq!(e.report().unwrap(),before);}
#[test]fn unresolved_quotes_and_insufficient_capital_cannot_be_imported_around(){let mut e=Engine::new_live(&policy()).unwrap();e.advance(&book("800","111","2026-10-14T23:59:59Z")).unwrap();let before=e.report().unwrap();assert!(e.advance(&adoption()).is_err());assert_eq!(e.report().unwrap(),before);let mut p=policy();p["maximumCommitted"]=json!("3.000000");let mut e=Engine::new_live(&p).unwrap();let before=e.report().unwrap();assert!(e.advance(&adoption()).is_err());assert_eq!(e.report().unwrap(),before);}
#[test]fn paper_wallet_cannot_adopt_actual_positions(){let mut e=Engine::new(&policy()).unwrap();assert!(e.advance(&adoption()).is_err());}
